-- Preserve logical search and existing rows; locate each derived row by indexed identity.
CREATE TABLE launch_search_rows (id INTEGER PRIMARY KEY, record_id TEXT NOT NULL, record_type TEXT NOT NULL, UNIQUE(record_id,record_type));
INSERT INTO launch_search_rows(id,record_id,record_type) SELECT rowid,record_id,record_type FROM launch_search;
DROP TRIGGER launch_search_campaigns_insert;
DROP TRIGGER launch_search_campaigns_update;
DROP TRIGGER launch_search_campaigns_delete;
CREATE TRIGGER launch_search_campaigns_insert AFTER INSERT ON campaigns BEGIN INSERT INTO launch_search_rows(record_id,record_type) VALUES(new.id,'Campaign'); INSERT INTO launch_search(rowid,record_id,campaign_id,record_type,body) VALUES((SELECT id FROM launch_search_rows WHERE record_id=new.id AND record_type='Campaign'),new.id,new.id,'Campaign',new.name||' '||new.code||' '||new.status_summary); END;
CREATE TRIGGER launch_search_campaigns_update AFTER UPDATE OF id,name,code,status_summary ON campaigns BEGIN DELETE FROM launch_search WHERE rowid=(SELECT id FROM launch_search_rows WHERE record_id=old.id AND record_type='Campaign'); UPDATE launch_search_rows SET record_id=new.id WHERE record_id=old.id AND record_type='Campaign'; INSERT INTO launch_search(rowid,record_id,campaign_id,record_type,body) VALUES((SELECT id FROM launch_search_rows WHERE record_id=new.id AND record_type='Campaign'),new.id,new.id,'Campaign',new.name||' '||new.code||' '||new.status_summary); END;
CREATE TRIGGER launch_search_campaigns_delete AFTER DELETE ON campaigns BEGIN DELETE FROM launch_search WHERE rowid=(SELECT id FROM launch_search_rows WHERE record_id=old.id AND record_type='Campaign'); DELETE FROM launch_search_rows WHERE record_id=old.id AND record_type='Campaign'; END;
